select row_number() over(ORDER by site_no) as row_no , *,(select cloud_company from om_cloud_tbl oct where cloud_no = ocst.cloud_no) as cloud_company from om_cloud_site_tbl ocst where site_manager = #{lgn_nm}
and site_name like concat('%', #{searchKeyword}, '%')
and site_address like concat('%', #{searchKeyword}, '%')
order by row_no desc
LIMIT #{size} OFFSET #{offset}

